<?php namespace App\Http\Controllers\Api\V1; use App\Http\Controllers\Controller; use App\Models\Place; use Illuminate\Http\Request; class FavouriteController extends Controller { public function index(Request $r){return ['data'=>$r->user()->favourites()->with('category')->get()];} public function store(Request $r,Place $place){$r->user()->favourites()->syncWithoutDetaching([$place->id]);return response()->json(['message'=>'Favourite saved'],201);} public function destroy(Request $r,Place $place){$r->user()->favourites()->detach($place->id);return response()->noContent();} }
